    <span class="lnq-per"><b>${l0.from===l0.due?`${wd(l0.from)}, ${dBR(l0.from).slice(0,5)}`:`${dBR(l0.from).slice(0,5)} – ${dBR(l0.due).slice(0,5)}`}</b><span>${nd} dia${nd>1?'s':''}${dDays(l0.from)>=0?` · começa ${relD(l0.from)}`:''}</span></span>
