 $$('[data-st]',f).forEach(b=>b.onclick=()=>{f.q.value=Math.min(op,Math.max(1,(+f.q.value||0)+ +b.dataset.st));up();});$$('.ax-rb [data-u]').forEach(b=>b.onclick=()=>{f.q.value=b.dataset.u;up();});f.addEventListener('input',up);up();
